"""#317 physical first-person learning followed by M11 cold recovery.

This is a SOFTWARE witness, not population efficacy: two independently
constructed current-generation M11 journals share fixed birth inputs to
test deterministic parity. Each actually physically executes and pays for
all learning; no owner is injected, patched, resurrected, or rolled back.
Fail closed unless positive bodily relief was REALLY observed in both.
"""
from pathlib import Path
from tempfile import TemporaryDirectory
import os
import subprocess
import sys
import unittest

ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/"scripts"))
from build_i1_fork import generate


class ActualLivedWaterCold317(unittest.TestCase):
    def test_positive_first_person_water_proof_survives_current_m11_cold(self):
        with TemporaryDirectory(prefix="i1-317-actual-living-water-") as temp:
            generated=Path(temp)/"generated"
            generate(generated)
            script="from copy import deepcopy\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nfrom i1lab.i1_natural_runtime import I1Runtime\nfrom i1lab.m11_transactional_mortal import M11TransactionalMortal\nfrom i1lab.sqlite_life_store import SQLiteLifeLedger\nfrom i1.modules.experienced_place_relevance import I1ExperiencedPlaceStage8, personally_supported_site_gain\nfrom run_i1_world_preset import _birth_parameters, load_preset\n\nworld, _ = load_preset(\"water-isolated-corridor\")\n# A real, non-privileged thirsty birth at a local water source; no motor,\n# motor policy, free calorie, memory or hidden map is forced into I1.\nworld = deepcopy(world)\nworld[\"initial_body\"][\"water\"] = 20\nparams,_ = _birth_parameters(world)\nlife_id=\"i1:317:m11:first-person-hydration-cold-v1\"\ndef fresh():\n    return I1Runtime(\n        birth_life_id=life_id, autonomous_mortal=True,\n        m11_sqlite_custody=True, wal_path=None,\n        i1_experienced_place_enabled=True,\n        diagnostic_sample_cost_uc=1, module_occupancy_cost_uc=1,\n        **params)\n\nwith TemporaryDirectory(prefix=\"m11-317-live-\") as d:\n    one=str(Path(d)/\"continuous.sqlite\")\n    two=str(Path(d)/\"cold.sqlite\")\n    history=[]\n    step_of_first_lived=None\n    owner_snapshot=None\n    with M11TransactionalMortal.birth(\n        db_path=one,runtime=fresh(),individual_id=life_id) as continuous:\n        with M11TransactionalMortal.birth(\n            db_path=two,runtime=fresh(),individual_id=life_id) as cold:\n            for _ in range(180):\n                a=continuous.run_step()\n                b=cold.run_step()\n                assert a.journal_head==b.journal_head\n                assert a.generation==b.generation and a.status==b.status\n                ca=continuous._runtime\n                cb=cold._runtime\n                assert isinstance(ca.stage8_option_evaluator,\n                                  I1ExperiencedPlaceStage8)\n                assert ca._water_learner.export_causal_state()==(\n                    cb._water_learner.export_causal_state())\n                if ca._water_learner.examples:\n                    step_of_first_lived=a.world_step\n                    owner_snapshot=ca._water_learner.export_causal_state()\n                    assert any(e.causal_event.get(\"kind\")==\n                       \"i1_water_lived_outcome_admitted\"\n                       for e in ca.journal.entries)\n                    assert personally_supported_site_gain(\n                        ca._water_learner,site=(8,8),life_id=life_id)>0\n                    break\n                if a.status==\"dead\":\n                    raise AssertionError(\n                        \"natural I1 died before positive first-person water learning\")\n            assert step_of_first_lived is not None, (\n                \"no positive personally observed boire under real motor control\")\n            audit=SQLiteLifeLedger.audit_read_only(\n                path=two,expected_individual_id=life_id)\n            assert audit.generation==step_of_first_lived\n            assert audit.may_recover and not audit.pending_intent\n        # This is one independent control life, never rewound or resumed\n        # from an older generation.\n        for _ in range(5):\n            a=continuous.run_step()\n            history.append((a.journal_head,a.world_step,a.status,\n                continuous._runtime._water_learner.export_causal_state()))\n            if a.status==\"dead\":\n                break\n    # Operator-only diagnostics: do not change the recovery fail-closed gate.\n    import i1lab.m11_transactional_mortal as cold_module\n    from i1lab.determinism import canonical_causal_bytes\n    real_installer=cold_module._install_trusted_current_on_fresh\n    def diagnosis(runtime,image,journal):\n        try:\n            return real_installer(runtime,image,journal)\n        except Exception as exc:\n            observed=cold_module._runtime_image(\n                runtime,individual_id=image[\"individual_id\"])\n            keys=[k for k in image\n                if canonical_causal_bytes(image[k]) !=\n                   canonical_causal_bytes(observed[k])]\n            owner_drift=[k for k in image[\"owners\"]\n                if canonical_causal_bytes(image[\"owners\"][k]) !=\n                   canonical_causal_bytes(observed[\"owners\"][k])]\n            local_drift=[k for k in image[\"runtime_local\"]\n                if canonical_causal_bytes(image[\"runtime_local\"][k]) !=\n                   canonical_causal_bytes(observed[\"runtime_local\"][k])]\n            raise AssertionError(\n                \"M11_EXACT_PARITY_FAILURE keys=\"+repr(keys)\n                +\" owners=\"+repr(owner_drift)+\" locals=\"+repr(local_drift)\n                +\" worldfields=\"+repr([k for k in image[\"world\"] if\n                   canonical_causal_bytes(image[\"world\"][k]) !=\n                   canonical_causal_bytes(observed[\"world\"][k])])) from exc\n    cold_module._install_trusted_current_on_fresh=diagnosis\n    with M11TransactionalMortal.cold_recover(\n        db_path=two,individual_id=life_id,\n        runtime_factory=fresh) as recovered:\n        assert recovered._runtime._water_learner.export_causal_state()==owner_snapshot\n        assert isinstance(recovered._runtime.stage8_option_evaluator,\n                          I1ExperiencedPlaceStage8)\n        assert personally_supported_site_gain(\n            recovered._runtime._water_learner,site=(8,8),life_id=life_id)>0\n        for head,step,status,water_owner in history:\n            receipt=recovered.run_step()\n            assert (receipt.journal_head,receipt.world_step,receipt.status)==(\n                head,step,status), \"native physical journal diverged after cold\"\n            assert recovered._runtime._water_learner.export_causal_state()==water_owner\n    print(\"I1_NATIVE_M11_LIVED_WATER_COLD_PARITY_OK\",\n          step_of_first_lived,len(history))\n"
            env=dict(os.environ)
            env["PYTHONPATH"]=(
                str(generated)+":"+str(ROOT/"src")+":"+str(ROOT/"tools"))
            p=subprocess.run([sys.executable,"-c",script],
                env=env,capture_output=True,text=True,check=False,timeout=240)
            self.assertEqual(p.returncode,0,p.stderr[-8000:])
            self.assertIn("I1_NATIVE_M11_LIVED_WATER_COLD_PARITY_OK",p.stdout)


if __name__=="__main__":
    unittest.main()
